import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
Eres el Asistente Virtual VIP de "Olas Home - Las Velas" en Paracas, Perú.
Tu objetivo es ayudar a los huéspedes con información sobre su estadía.
Detalles importantes:
- La propiedad tiene WiFi (Red: OlasHome_Velas, Clave: paracas2024).
- El Jacuzzi está disponible pero requiere cuidado (no aceites).
- El registro en el Excel de vigilancia es OBLIGATORIO antes de llegar.
- Estamos cerca de la Reserva de Paracas y el puerto para las Islas Ballestas.
- Habla siempre de forma elegante, servicial y minimalista.
- Si no sabes algo, pide que contacten al host vía WhatsApp.
- Responde siempre en español.
`;

export async function chatWithAI(prompt: string, history: { role: 'user' | 'assistant', content: string }[]) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    return response.text || "Lo siento, tuve un problema al procesar tu solicitud. Por favor contacta al host.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Mi conexión está un poco inestable frente al mar. ¿Podrías intentar de nuevo o contactar al host?";
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { chatWithAI } from '../services/geminiService';
import { Message } from '../types';

export const AIChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: '¡Hola! Soy tu asistente de Olas Home. ¿En qué puedo ayudarte con tu estadía hoy?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsLoading(true);

    const response = await chatWithAI(userMsg, messages);
    setMessages(prev => [...prev, { role: 'assistant', content: response }]);
    setIsLoading(false);
  };

  return (
    <>
      {/* Toggle Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-24 right-6 w-14 h-14 bg-[#1B365D] text-white rounded-full shadow-2xl flex items-center justify-center z-50 hover:scale-110 transition-transform"
      >
        <i className={`fas ${isOpen ? 'fa-times' : 'fa-comment-dots'} text-xl`}></i>
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-40 right-6 left-6 md:left-auto md:w-96 bg-white rounded-2xl shadow-2xl z-50 overflow-hidden flex flex-col border border-gray-100 animate-in slide-in-from-bottom-5">
          <div className="bg-[#1B365D] p-4 text-white flex justify-between items-center">
            <h3 className="font-medium">Olas Concierge AI</h3>
            <span className="text-xs opacity-75">Online</span>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 h-80">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                  msg.role === 'user' 
                    ? 'bg-[#C2A878] text-white rounded-tr-none' 
                    : 'bg-gray-100 text-[#1B365D] rounded-tl-none'
                }`}>
                  {msg.content}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-gray-100 p-3 rounded-2xl rounded-tl-none animate-pulse">
                  <span className="flex space-x-1">
                    <span className="w-1.5 h-1.5 bg-gray-400 rounded-full"></span>
                    <span className="w-1.5 h-1.5 bg-gray-400 rounded-full"></span>
                    <span className="w-1.5 h-1.5 bg-gray-400 rounded-full"></span>
                  </span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          <div className="p-4 border-t border-gray-100 flex gap-2">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Escribe tu duda aquí..."
              className="flex-1 bg-gray-50 border-none rounded-full px-4 py-2 text-sm focus:ring-2 focus:ring-[#C2A878] outline-none"
            />
            <button 
              onClick={handleSend}
              className="w-10 h-10 bg-[#C2A878] text-white rounded-full flex items-center justify-center"
            >
              <i className="fas fa-paper-plane text-sm"></i>
            </button>
          </div>
        </div>
      )}
    </>
  );
};

