        </section>
      </main>

      {/* Luxury Bottom Navigation */}
      <nav className="fixed bottom-6 left-6 right-6 h-16 bg-[#1B365D] text-white rounded-2xl shadow-2xl flex items-center justify-around px-4 z-40">
